def longest(strings: List[str]) -> Optional[str]:
    """ O(n log n) for sorting, O(n) for finding the longest one. """
    if not strings:
        return None

    shortest, longest = strings[0], strings[0]

    for string in strings[1:]:
        if len(string) > len(shortest):
            shortest, longest = string, shortest

        if len(string) > len(longest):
            longest = string

    if longest == shortest:  # Only one string
        return ''.join(shortest)

    return longest
