def factorize(n: int) -> List[int]:
    result = []
    while n % 2 == 0:
        result.append(2)
        n = n / 2
    f = 3
    while f * f <= n:
        if n % f == 0:
            result.append(f)
            n = n / f
        else:
            f += 2
    if n > 1:
        result.append(n)
    return result
