def same_chars(s0: str, s1: str) -> bool:
    """
    Check if two words have the same characters.
    """
    if len(s0) != len(s1):
        return False
    mapping = {}
    for char in s0:
        if char not in mapping:
            mapping[char] = 0
        mapping[char] += 1
    for char in s1:
        if char not in mapping:
            return False
        mapping[char] -= 1
        if mapping[char] < 0:
            return False
    return True
